import MagicString from "magic-string";
import { Marked } from "marked";
import { encodeAndDecodeString, getHighlightLinesFromInfo } from "#lib/components/ui/code-block/core.js";
import { parsePackageCommand } from "#lib/components/ui/package-command/core.js";
import { getFileData } from "./utils.js";
import type { Plugin } from "vite";
const marked = new Marked();
const CWD = process.cwd();
const FILE_FILTER = new RegExp(`${CWD}/src/routes/.*\\.svx$`);

/** Simple plugin to allow  */
export default function svxPlugin(): Plugin {
	return {
		name: "svxPlugin",
		enforce: "pre",
		// Transform svx file to svelte
		transform: {
			filter: { id: FILE_FILTER },
			async handler(fileCode, filePath) {
				const fileData = getFileData(fileCode);
				const markedTokens = marked.lexer(fileData.markdown);

				// const pageData = CACHED_SVX_FILES.get(filePath)!;
				const s = new MagicString(fileCode);
				const html = await Promise.all(
					markedTokens.map(async (token) => {
						if (token.type === "code") {
							// Read `{1,3-5}` line highlights before splitting the language and title.
							const { highlightLines, info } = getHighlightLinesFromInfo(token.lang || "");
							const [lang = "", prepPath] = info.split(/\s+/);
							const title = prepPath?.match(/^(?:title=")?([^"]+)"?$/)?.[1];
							// A `pm` fence holds one npm command and renders a tab for each package manager; the shared key keeps the reader's choice on every page.
							const packageCommand = lang === "pm" ? parsePackageCommand(token.text) : undefined;
							if (packageCommand) {
								return `<PackageCommand style="margin-top: 1rem;" type="${packageCommand.type}" command={${JSON.stringify(packageCommand.command)}} dev={${packageCommand.dev}} managers={["pnpm", "bun", "npm", "yarn"]} storageKey="plainsv-package-manager" />`;
							}
							// Every other fence is a code block; a `pm` fence that is not a known npm command falls back to bash.
							return `<CodeBlock usingEncodedData style="margin-top: 1rem;" ${highlightLines ? `highlightLines="${highlightLines}" ` : ""}data={{ ${title ? `path: "${title}"` : `lang: "${lang === "pm" ? "bash" : lang}"`}, code: "${encodeAndDecodeString(token.text, "encode")}" }}>
								<CodeBlockHeader />
								<CodeBlockCode />
							</CodeBlock>`;
						}
						// Return raw component to allow preview and all that
						if (token.type === "html" && /^\s*<[A-Z]/.test(token.raw)) {
							return token.raw;
						} else {
							return marked.parse(token.raw.replaceAll("{", "&#123;").replaceAll("}", "&#125;").replaceAll("→", "s"));
						}
					}),
				);

				// Return transformed code
				return {
					map: s.generateMap({ hires: true }),
					code: `<script lang="ts">\n    ${fileData.scriptData}\n
						import { PageMeta } from "#lib/components/shared/index.js";
						import { CodeBlock, CodeBlockCode, CodeBlockHeader } from "#lib/components/ui/code-block/index.js";
						import { PackageCommand } from "#lib/components/ui/package-command/index.js";
					</script>

					<PageMeta title="${fileData.frontmatter.title}" description="${fileData.frontmatter.description}" />
					\n${html.join("\n")}

					<style>${fileData.styleData}</style>`,
				};
			},
		},
	};
}

import fs from "node:fs/promises";
import path from "node:path";

/** Get all `.svx` files inside routes folder */
export async function getAllSvxFiles(directory = `${process.cwd()}/src/routes`, fileList: string[] = []) {
	const files = await fs.readdir(directory);
	for (const file of files) {
		const filePath = path.join(directory, file);
		const stat = await fs.stat(filePath);
		const isAFolder = stat.isDirectory();
		// if it's a directory
		if (isAFolder) await getAllSvxFiles(filePath, fileList);
		// else if if is not return folder only, add file to list
		else if (filePath.endsWith("+page.svx")) fileList.push(filePath);
	}
	return fileList;
}

/** Get frontmatter, script tag, and clean markdown from given file */
export function getFileData(fileData: string) {
	const frontmatter: Record<string, string> = {};
	const frontmatterMatch = fileData.match(/^---\n([\s\S]*?)\n---(?:\n|$)/);
	const searchableData = getSearchableData(fileData);
	const scriptMatch = searchableData.match(/<script\b[^>]*>([\s\S]*?)<\/script>/);
	const scriptRawTag = scriptMatch?.[0] ?? "";
	const scriptData = scriptMatch?.[1]?.trim() ?? "";
	const styleMatch = searchableData.match(/<style\b[^>]*>([\s\S]*?)<\/style>/);
	const styleRawTag = styleMatch?.[0] ?? "";
	const styleData = styleMatch?.[1]?.trim() ?? "";

	// Else loop all data as lines
	if (frontmatterMatch) {
		for (const line of frontmatterMatch[0].split("\n").filter(Boolean)) {
			const keyValueMatch = line.match(/^(\w+):\s*(.+)$/);
			// If not a valid key: continue/skip
			if (!keyValueMatch) continue;
			// Else handle key
			const key = keyValueMatch[1].trim().replace(/^['"]|['"]$/g, "");
			const value = keyValueMatch[2].trim().replace(/^['"]|['"]$/g, "");
			frontmatter[key] = value;
		}
	}

	// Get script tag and remove frontmatter tag and script tag from markdown
	const markdown = fileData.replace(frontmatterMatch![0], "").replace(scriptRawTag, "").replace(styleRawTag, "").trim();
	return { frontmatter, scriptData, styleData, markdown };
}

/** Mask standalone Markdown fences while preserving character positions. */
function getSearchableData(fileData: string) {
	// Track the active fence's character (` or ~) and opening length.
	let fence: { marker: string; length: number } | undefined;
	// Process each line, including its newline.
	return fileData.replace(/^.*(?:\r?\n|$)/gm, (line) => {
		// Recognize 3+ backticks or tildes, indented by up to 3 spaces.
		const match = line.match(/^ {0,3}(`{3,}|~{3,})(.*?)(?:\r?\n)?$/);
		// Remember whether this line started inside a fenced block,
		// so the closing fence is masked too.
		const insideFence = Boolean(fence);
		if (match) {
			const [, markers, rest] = match;
			if (!fence) {
				// A backtick fence's trailing text cannot contain backticks.
				if (markers[0] !== "`" || !rest.includes("`")) {
					fence = { marker: markers[0], length: markers.length };
				}
			} else if (
				// Closing fences must use the same character,
				// be at least as long, and have only whitespace after them.
				markers[0] === fence.marker &&
				markers.length >= fence.length &&
				/^[ \t]*$/.test(rest)
			) {
				fence = undefined;
			}
		}
		// Mask the opening fence, its contents, and the closing fence.
		// Preserve newlines and string length so positions stay unchanged.
		return insideFence || fence ? line.replace(/[^\r\n]/g, " ") : line;
	});
}
